export function translator(language) {
  const localized = language?.startsWith("sv") ? sv : undefined;
  return (key) => {
    if (!Object.hasOwn(en, key)) {
      return key;
    }
    const translationKey = key;
    return localized?.[translationKey] ?? en[translationKey];
  };
}
